#include "modbus.h"
#include "../../config.mcc/mcc_generated_files/system/system.h"
#include "../registers.h"
#include <string.h>
#include <util/crc16.h>

#define MODBUS_BUF_SIZE 256

volatile uint8_t rx_buffer[MODBUS_BUF_SIZE];
volatile uint16_t rx_count = 0;

volatile bool modbus_frame_ready = false;

void UART0_RxCompleteCallBack(void) {
  uint8_t data = USART0_Read(); // USART0.RXDATAL;

  if (!modbus_frame_ready && rx_count < MODBUS_BUF_SIZE) {
    rx_buffer[rx_count++] = data;

    // Restart the TCB single-shot timer after every received byte.
    TCB0_CounterSet(0);
    TCB0_Start();
  }
}

void TCB0_CaptureCallback(void) {
  TCB0_Stop();

  if (rx_count >= 4) {
    modbus_frame_ready = true;
  } else {
    // Discard incomplete or invalid frames.
    rx_count = 0;
  }
}

void Modbus_Init(void) {
  USART0_RxCompleteCallbackRegister(UART0_RxCompleteCallBack);
  TCB0_CounterSet(0);
  TCB0_Stop();
  TCB0_CaptureCallbackRegister(TCB0_CaptureCallback);
}

static void Modbus_SendFrame(const modbus_frame_t *frame,
                             uint8_t payload_size) {
  const uint8_t *byte_stream = (const uint8_t *)frame;

  // Send the payload and append the Modbus CRC in little-endian order.
  uint16_t crc = 0xFFFF;
  for (uint8_t i = 0; i < payload_size; i++) {
    USART0_Write(byte_stream[i]);
    crc = _crc16_update(crc, byte_stream[i]);
  }
  USART0_Write((uint8_t)(crc & 0xFF));
  USART0_Write((uint8_t)(crc >> 8));
}

static void Modbus_WriteSingleCoil(const modbus_frame_t *frame) {
  uint16_t address =
      Modbus_SwapBytes16(frame->payload.req_write_single.address);
  if (address >= MODBUS_COIL_ADDRESS_MIN &&
      address <= MODBUS_COIL_ADDRESS_MAX) {
    uint16_t byte_index = address / 8;
    uint8_t bit_index = address % 8;

    if (byte_index < GLOBAL_SHADOW_SIZE) {
      uint8_t clear_bit_mask = (uint8_t)~(1U << bit_index);

      // Update only the addressed coil and preserve the other bits.
      global_shadow_ram[byte_index] =
          (global_shadow_ram[byte_index] & clear_bit_mask) |
          ((frame->payload.req_write_single.value & 1U) << bit_index);
    }
  }

  // The response echoes the complete request.
  Modbus_SendFrame(frame, 6);
}

void Modbus_ProcessMessage(void) {
  modbus_frame_t frame;

  if (rx_buffer[0] != MODBUS_ID_DEVICE) {
    return;
  }

  // Validate the CRC before interpreting the frame.
  uint16_t crc = rx_buffer[rx_count - 2] | (rx_buffer[rx_count - 1] << 8);
  uint16_t calc_crc = 0xFFFF;
  for (size_t i = 0; i < rx_count - 2; i++) {
    calc_crc = _crc16_update(calc_crc, rx_buffer[i]);
  }

  if (crc != calc_crc) {
    return;
  }

  memcpy(&frame, (const void *)rx_buffer, rx_count - 2);

  switch (frame.function_code) {
  case MODBUS_READ_COILS:
    break;
  case MODBUS_READ_DISCRETE_INPUT:
    break;
  case MODBUS_READ_HOLDING_REGISTERS:
    break;
  case MODBUS_READ_INPUT_REGISTERS:
    break;
  case MODBUS_WRITE_SINGLE_COIL:
    Modbus_WriteSingleCoil(&frame);
    break;
  case MODBUS_WRITE_SINGLE_REGISTER:
    break;
  case MODBUS_WRITE_MULTIPLE_COILS:
    break;
  case MODBUS_WRITE_MULTIPLE_REGISTERS:
    break;
  }
}

void Modbus_Loop(void) {
  if (modbus_frame_ready) {
    Modbus_ProcessMessage();

    memset((void *)rx_buffer, 0, sizeof(rx_buffer));
    rx_count = 0;
    modbus_frame_ready = false;
  }
}
